// Python-compatible JSON serialization (json.dumps defaults) and
// Python-compatible repr() for str / dict, so printed output matches
// CPython byte-for-byte.

// --- json.dumps(value, ensure_ascii=True, separators=(', ', ': ')) ---

function escapeJsonString(s) {
  let out = '"';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    switch (ch) {
      case '"': out += '\\"'; continue;
      case '\\': out += '\\\\'; continue;
      case '\b': out += '\\b'; continue;
      case '\f': out += '\\f'; continue;
      case '\n': out += '\\n'; continue;
      case '\r': out += '\\r'; continue;
      case '\t': out += '\\t'; continue;
    }
    if (cp < 0x20) {
      out += '\\u' + cp.toString(16).padStart(4, '0');
    } else if (cp < 0x7f) {
      out += ch;
    } else {
      // ensure_ascii=True: emit UTF-16 code units as \uXXXX escapes
      if (cp > 0xffff) {
        const v = cp - 0x10000;
        const hi = 0xd800 + (v >> 10);
        const lo = 0xdc00 + (v & 0x3ff);
        out += '\\u' + hi.toString(16).padStart(4, '0');
        out += '\\u' + lo.toString(16).padStart(4, '0');
      } else {
        out += '\\u' + cp.toString(16).padStart(4, '0');
      }
    }
  }
  return out + '"';
}

export function pyJsonDumps(value) {
  if (value === null) return 'null';
  if (value === true) return 'true';
  if (value === false) return 'false';
  if (typeof value === 'string') return escapeJsonString(value);
  if (typeof value === 'number') {
    if (Number.isInteger(value)) return String(value);
    return String(value);
  }
  if (Array.isArray(value)) {
    return '[' + value.map(pyJsonDumps).join(', ') + ']';
  }
  if (typeof value === 'object') {
    const items = Object.keys(value).map(
      (k) => escapeJsonString(k) + ': ' + pyJsonDumps(value[k])
    );
    return '{' + items.join(', ') + '}';
  }
  throw new TypeError(`Object of type ${typeof value} is not JSON serializable`);
}

// --- Python repr() for str ---

export function pyReprStr(s) {
  // CPython prefers single quotes; switches to double quotes only when the
  // string contains a single quote but no double quote.
  let quote = "'";
  if (s.includes("'") && !s.includes('"')) {
    quote = '"';
  }
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (cp < 0x20 || cp === 0x7f) {
      out += '\\x' + cp.toString(16).padStart(2, '0');
    } else {
      out += ch;
    }
  }
  return out + quote;
}

// --- Python repr() for dicts of string keys (insertion order) ---

export function pyRepr(value) {
  if (typeof value === 'string') return pyReprStr(value);
  if (value === null) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (typeof value === 'number') return String(value);
  if (Array.isArray(value)) {
    return '[' + value.map(pyRepr).join(', ') + ']';
  }
  if (typeof value === 'object') {
    const items = Object.keys(value).map(
      (k) => pyReprStr(k) + ': ' + pyRepr(value[k])
    );
    return '{' + items.join(', ') + '}';
  }
  return String(value);
}

