export class JWSSignatureError extends JWTError {
  constructor(message = 'Signature verification failed.') {
    super(message);
  }
}
export class JWTClaimsError extends JWTError {
  constructor(message = 'Invalid claims') {
    super(message);
  }
}

function sign(signingInput, key) {
  return hmacSha256(encoder.encode(key), encoder.encode(signingInput));
}

export function encode(claims, key, { algorithm = 'HS256' } = {}) {
  if (algorithm !== 'HS256') {
    throw new JWTError(`Algorithm not supported: ${algorithm}`);
  }
  // jose serializes the header with compact separators and the payload
  // with json.dumps' default separators.
  const headerJson = JSON.stringify({ alg: algorithm, typ: 'JWT' });
  const payloadJson = pyJsonDumps(claims);
  const segments = [
    base64urlEncode(encoder.encode(headerJson)),
    base64urlEncode(encoder.encode(payloadJson)),
  ];
  const signingInput = segments.join('.');
  segments.push(base64urlEncode(sign(signingInput, key)));
  return segments.join('.');
}

function timingSafeEqualStr(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return diff === 0;
}

export function decode(token, key, { algorithms = null, options = {} } = {}) {
  const parts = token.split('.');
  if (parts.length !== 3) {
    throw new JWTError('Not enough segments');
  }
  const [headerB64, payloadB64, signatureB64] = parts;

  let header;
  try {
    header = JSON.parse(decoder.decode(base64urlDecode(headerB64)));
  } catch {
    throw new JWTError('Invalid header string: must be a json object');
  }
  const algorithm = header.alg;
  if (algorithms && !algorithms.includes(algorithm)) {
    throw new JWTError('The specified alg value is not allowed');
  }
  if (algorithm !== 'HS256') {
    throw new JWTError(`Algorithm not supported: ${algorithm}`);
  }

  // Verify signature
  const signingInput = headerB64 + '.' + payloadB64;
  const expected = base64urlEncode(sign(signingInput, key));
  if (!timingSafeEqualStr(expected, signatureB64)) {
    throw new JWSSignatureError();
  }

  let claims;
  try {
    claims = JSON.parse(decoder.decode(base64urlDecode(payloadB64)));
  } catch {
    throw new JWTError('Invalid payload string: must be a json object');
  }

  // Claim verification driven by options (mirrors jose defaults: every
  // verify_* option defaults to True unless explicitly disabled).
  const verifySub = options.verify_sub !== undefined ? options.verify_sub : true;
  if (verifySub && !('sub' in claims)) {
    throw new JWTClaimsError('Missing sub claim');
  }

  return claims;
}

