// Node.js (ESM) port of /workspace/dataset/test10.py.
// Encodes a JWT containing a subject claim, prints it, then decodes it
// with sub verification enabled and prints the claims using Python's
// dict repr formatting.

import { parseArgs } from './lib/argparse.mjs';
import { encode, decode } from './lib/jwt.mjs';
import { pyRepr } from './lib/pyjson.mjs';

const args = parseArgs(process.argv.slice(2));

// 创建带subject的token
const secret = 'key';
const payload = {
  sub: args.subject,
  data: args.user_data,
};
const token = encode(payload, secret);
console.log(token);

// 解码时验证subject（通过options参数）
const decoded = decode(token, secret, {
  options: { verify_sub: true },
  algorithms: ['HS256'],
});
console.log(pyRepr(decoded));

